<?php if (get_instance()->permissions('service_jobs_add')): ?><details class="garden-card"><summary class="garden-create-summary"><span><i class="fa fa-plus" aria-hidden="true"></i> New maintenance plan</span><small>Set a repeat visit schedule</small></summary><form class="garden-card" method="post" action="<?= base_url('garden/create_schedule'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="request_key" value="<?= $request_key; ?>"><h2>New Maintenance Schedule</h2>
<?php $this->load->view('garden/service_customer_fields'); ?>
<label>Service / Visit Title<input name="title" maxlength="200" required></label><div class="garden-grid"><label>Start Date<input type="date" name="start_date" required></label><label>End Date (optional)<input type="date" name="end_date"></label>
<label>Frequency<select name="frequency" data-garden-select hidden><?php foreach (['once'=>'One-time','weekly'=>'Weekly','biweekly'=>'Biweekly','monthly'=>'Monthly','custom'=>'Custom Days'] as $value=>$label): ?><option value="<?= $value; ?>"><?= $label; ?></option><?php endforeach; ?></select></label><label>Custom Interval in Days<input type="number" name="custom_days" min="1" max="366"></label></div><button class="garden-button">Create Schedule</button></form></details><?php endif; ?>
<section class="garden-card"><h2>Recurring Services</h2><p class="garden-muted">Generate up to 100 visits per action, at most one year ahead. Generated visits are pending; team availability must be confirmed. Cancelling a schedule stops future generation; existing visits retain their history and can be cancelled individually. No invoices are generated automatically.</p>
<?php foreach ($garden_schedules as $schedule): ?><article class="garden-card"><h2><?= htmlspecialchars($schedule->title); ?></h2><p><?= htmlspecialchars($schedule->customer_name.' · '.$schedule->frequency.' · '.$schedule->status); ?></p>
<?php if ($schedule->status==='active' && get_instance()->permissions('service_jobs_add')): ?><form method="post" action="<?= base_url('garden/generate_visits'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="schedule_id" value="<?= (int)$schedule->id; ?>"><label>Generate Visits Through<input type="date" name="through" value="<?= date('Y-m-d',strtotime('+1 month')); ?>" required></label><button class="garden-button">Generate Pending Visits</button></form><?php endif; ?>
<?php if ($schedule->status==='active' && get_instance()->permissions('service_jobs_edit')): ?><form method="post" action="<?= base_url('garden/cancel_schedule'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="schedule_id" value="<?= (int)$schedule->id; ?>"><button class="garden-button">Stop Future Generation</button></form><?php endif; ?></article><?php endforeach; ?>
<?php if (!$garden_schedules): ?><p>No maintenance schedules yet.</p><?php endif; ?>
<a href="<?= base_url('garden/work'); ?>">Open Shared Service Jobs to Assign, Complete or Reschedule Visits</a></section>
